    public Resource? file_resource_to_embedded(Variant value,Resource property)
    {
        if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource resource)return resource.Duplicate(true);string path=value.ToString();if(path.Length==0||!FileAccess.FileExists(path))return null;if(is_shader_property(property)){var shader=ResourceLoader.Load<Shader>(path,"",ResourceLoader.CacheMode.Ignore);return shader?.Duplicate(true);}if(is_mesh_property(property)){var mesh=path.GetExtension().ToLowerInvariant() is "glb" or "gltf" or "fbx"?_modelImport.load_3d_model(path):ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);return mesh is Mesh or PackedScene?mesh.Duplicate(true):null;}if(Extensions(property).Contains("mp3"))return GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",path).As<Resource>();if(property.Get("options").AsGodotDictionary().GetValueOrDefault("shader_texture",false).AsBool()&&path.GetExtension().ToLowerInvariant() is "tres" or "res"){var loaded=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);if(loaded is Texture2D)return loaded.Duplicate(true);return ActorDataOperations.ScriptIs(loaded,"res://scripts/actors/core/actor_object_data.gd")?_data.from_object(_data.copy_object(loaded!)):null;}using var image=Image.LoadFromFile(path);if(image==null||image.IsEmpty())return null;var texture=ImageTexture.CreateFromImage(image);texture.ResourceName=path.GetFile().GetBaseName();return texture;
    }
    public bool write_file_resource(Variant value,string path)
    {
        var resource=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;if(ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_reference.gd")){var data=_animation.resolve_reference(resource!);return data!=null&&ResourceSaver.Save(data,path)==Error.Ok;}if(value.VariantType==Variant.Type.String){string source=value.AsString();if(source.StartsWith("res://",StringComparison.Ordinal))source=ProjectSettings.GlobalizePath(source);return DirAccess.CopyAbsolute(source,path)==Error.Ok;}if(resource is Shader shader){using var file=FileAccess.Open(path,FileAccess.ModeFlags.Write);if(file==null)return false;file.StoreString(shader.Code);return true;}if(resource is Mesh or PackedScene)return ResourceSaver.Save(resource,path)==Error.Ok;var image=resource is Texture2D texture?texture.GetImage():resource as Image;return image!=null&&image.SavePng(path)==Error.Ok;
    }
    private static bool ScriptNode(Node node,string path){var script=node.GetScript().As<Script>();while(script!=null){if(script.ResourcePath==path||script.ResourcePath==LegacyResourceLoader.NativeScriptPath(path))return true;script=script.GetBaseScript();}return false;}
